(function restoreATCTargetOnLoad() {
    function restore() {
        try {
            const stored = localStorage.getItem('atc_selected_target');
            if (!stored) return;
            const parsed = JSON.parse(stored);
            const el = document.getElementById('target-card-' + parsed.name);
            if (el) el.classList.add('active');
        } catch(e) {}
    }
